   154→// ShouldSkipOnDefaultBranchForStrategy checks if we're on the default branch and
   155→// whether the current strategy allows operating on it.
   156→// Returns (shouldSkip, branchName). If shouldSkip is true, the caller should
   157→// skip the operation. Shadow strategies return false (allowing main branch).
   158→func ShouldSkipOnDefaultBranchForStrategy() (bool, string) {
   159→	isDefault, branchName, err := IsOnDefaultBranch()
   160→	if err != nil {
   161→		// If we can't determine, allow the operation
   162→		return false, ""
   163→	}
   164→	if !isDefault {
   165→		return false, branchName
   166→	}
   167→
   168→	// Check if the current strategy allows main branch
   169→	start := GetStrategy()
   170→
   171→	if start.AllowsMainBranch() {
   172→		return false, branchName
   173→	}
   174→
   175→	return true, branchName
   176→}
