   198→// GetMergeBase finds the common ancestor (merge-base) between two branches.
   199→// Returns the hash of the merge-base commit.
   200→func GetMergeBase(branch1, branch2 string) (*plumbing.Hash, error) {
   201→	repo, err := openRepository()
   202→	if err != nil {
   203→		return nil, fmt.Errorf("failed to open git repository: %w", err)
   204→	}
   205→
   206→	// Resolve branch references
   207→	ref1, err := repo.Reference(plumbing.NewBranchReferenceName(branch1), true)
   208→	if err != nil {
   209→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch1, err)
   210→	}
   211→
   212→	ref2, err := repo.Reference(plumbing.NewBranchReferenceName(branch2), true)
   213→	if err != nil {
   214→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch2, err)
   215→	}
   216→
   217→	// Get commit objects
   218→	commit1, err := repo.CommitObject(ref1.Hash())
   219→	if err != nil {
   220→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch1, err)
   221→	}
   222→
   223→	commit2, err := repo.CommitObject(ref2.Hash())
   224→	if err != nil {
   225→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch2, err)
   226→	}
   227→
   228→	// Find common ancestor
   229→	mergeBase, err := commit1.MergeBase(commit2)
   230→	if err != nil {
   231→		return nil, fmt.Errorf("failed to find merge base: %w", err)
   232→	}
   233→
   234→	if len(mergeBase) == 0 {
   235→		return nil, errors.New("no common ancestor found")
   236→	}
   237→
   238→	hash := mergeBase[0].Hash
   239→	return &hash, nil
   240→}
