   264→// findNewUntrackedFiles finds files that are newly untracked (not in pre-existing list)
   265→func findNewUntrackedFiles(current, preExisting []string) []string {
   266→	preExistingSet := make(map[string]bool)
   267→	for _, file := range preExisting {
   268→		preExistingSet[file] = true
   269→	}
   270→
   271→	var newFiles []string
   272→	for _, file := range current {
   273→		if !preExistingSet[file] {
   274→			newFiles = append(newFiles, file)
   275→		}
   276→	}
   277→	return newFiles
   278→}
