   318→// CheckoutBranch switches to the specified local branch or commit.
   319→// Uses git CLI instead of go-git to work around go-git v5 bug where Checkout
   320→// deletes untracked files (see https://github.com/go-git/go-git/issues/970).
   321→// Should be switched back to go-git once we upgrade to go-git v6
   322→// Returns an error if the ref doesn't exist or checkout fails.
   323→func CheckoutBranch(ref string) error {
   324→	ctx := context.Background()
   325→	cmd := exec.CommandContext(ctx, "git", "checkout", ref)
   326→	if output, err := cmd.CombinedOutput(); err != nil {
   327→		return fmt.Errorf("checkout failed: %s: %w", strings.TrimSpace(string(output)), err)
   328→	}
   329→	return nil
   330→}
