   332→// FetchAndCheckoutRemoteBranch fetches a branch from origin and creates a local tracking branch.
   333→func FetchAndCheckoutRemoteBranch(branchName string) error {
   334→	repo, err := openRepository()
   335→	if err != nil {
   336→		return fmt.Errorf("failed to open repository: %w", err)
   337→	}
   338→
   339→	// Fetch the specific branch from origin
   340→	remote, err := repo.Remote("origin")
   341→	if err != nil {
   342→		return fmt.Errorf("failed to get origin remote: %w", err)
   343→	}
   344→
   345→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
   346→	err = remote.Fetch(&git.FetchOptions{
   347→		RefSpecs: []config.RefSpec{config.RefSpec(refSpec)},
   348→	})
   349→	if err != nil && !errors.Is(err, git.NoErrAlreadyUpToDate) {
   350→		return fmt.Errorf("failed to fetch branch from origin: %w", err)
   351→	}
   352→
   353→	// Get the remote branch reference
   354→	remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
   355→	if err != nil {
   356→		return fmt.Errorf("branch '%s' not found on origin: %w", branchName, err)
   357→	}
   358→
   359→	// Create local branch pointing to the same commit
   360→	localRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
   361→	err = repo.Storer.SetReference(localRef)
   362→	if err != nil {
   363→		return fmt.Errorf("failed to create local branch: %w", err)
   364→	}
   365→
   366→	// Checkout the new local branch
   367→	return CheckoutBranch(branchName)
   368→}
