    71→// isPushSessionsDisabled checks if push_sessions is disabled in settings.
    72→// Returns true if push_sessions is explicitly set to false.
    73→// Checks settings.local.json first (user preference), then settings.json (shared).
    74→func isPushSessionsDisabled() bool {
    75→	// Use repo root to find settings files when run from a subdirectory
    76→	localSettingsPath, err := paths.AbsPath(".entire/settings.local.json")
    77→	if err != nil {
    78→		localSettingsPath = ".entire/settings.local.json" // Fallback
    79→	}
    80→	sharedSettingsPath, err := paths.AbsPath(".entire/settings.json")
    81→	if err != nil {
    82→		sharedSettingsPath = ".entire/settings.json" // Fallback
    83→	}
    84→
    85→	// Try local settings first (user preference, not committed)
    86→	if disabled, found := readPushSessionsFromFile(localSettingsPath); found {
    87→		return disabled
    88→	}
    89→
    90→	// Fall back to shared settings
    91→	if disabled, found := readPushSessionsFromFile(sharedSettingsPath); found {
    92→		return disabled
    93→	}
    94→
    95→	// Default: push is enabled
    96→	return false
    97→}
