    99→// readPushSessionsFromFile reads push_sessions from a specific settings file.
   100→// Returns (isDisabled, found). If not found, returns (false, false).
   101→func readPushSessionsFromFile(settingsPath string) (bool, bool) {
   102→	//nolint:gosec // G304: settingsPath is always a hardcoded constant from this package
   103→	data, err := os.ReadFile(settingsPath)
   104→	if err != nil {
   105→		return false, false
   106→	}
   107→
   108→	var settings struct {
   109→		StrategyOptions map[string]interface{} `json:"strategy_options"`
   110→	}
   111→	if err := json.Unmarshal(data, &settings); err != nil {
   112→		return false, false
   113→	}
   114→
   115→	if settings.StrategyOptions == nil {
   116→		return false, false
   117→	}
   118→
   119→	val, exists := settings.StrategyOptions["push_sessions"]
   120→	if !exists {
   121→		return false, false
   122→	}
   123→
   124→	// Handle boolean value
   125→	if boolVal, ok := val.(bool); ok {
   126→		return !boolVal, true // disabled = !push_sessions
   127→	}
   128→
   129→	return false, false
   130→}
