   132→// doPushSessionsBranch pushes the sessions branch to the remote.
   133→func doPushSessionsBranch(remote, branchName string) error {
   134→	fmt.Fprintf(os.Stderr, "[entire] Pushing session logs to %s...\n", remote)
   135→
   136→	// Try pushing first
   137→	if err := tryPushSessionsCommon(remote, branchName); err == nil {
   138→		return nil
   139→	}
   140→
   141→	// Push failed - likely non-fast-forward. Try to fetch and merge.
   142→	fmt.Fprintf(os.Stderr, "[entire] Syncing with remote session logs...\n")
   143→
   144→	if err := fetchAndMergeSessionsCommon(remote, branchName); err != nil {
   145→		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync sessions: %v\n", err)
   146→		return nil // Don't fail the main push
   147→	}
   148→
   149→	// Try pushing again after merge
   150→	if err := tryPushSessionsCommon(remote, branchName); err != nil {
   151→		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push sessions after sync: %v\n", err)
   152→	}
   153→
   154→	return nil
   155→}
